package com.crizz.apex;
import android.app.Activity; import android.os.Bundle; import android.view.*; import android.graphics.*; import java.util.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);setContentView(new Arena());}
 class Arena extends View {
 Paint p=new Paint(3); int n=0; Car[] cars; long last; float W=1200,H=650; int winner=-1; int[] models={0,1,2}; HashMap<Integer,float[]> fingers=new HashMap<>();
 int[] colors={0xff38caff,0xffff536d,0xffa8ed54}; String[] names={"SPORT","F1","TRUCK"};
 class Car {float x,y,vx,vy,a,hp=100,mass,spin; int type; Car(float x,float y,float a,int t){this.x=x;this.y=y;this.a=a;type=t;mass=t==2?1.7f:t==1?.8f:1;}}
 Arena(){super(MainActivity.this);setLayerType(View.LAYER_TYPE_HARDWARE,null);}
 void start(int count){n=count;winner=-1;fingers.clear();cars=new Car[n];for(int i=0;i<n;i++)cars[i]=new Car(300+i*300,300,i==0?0:180,models[i]);last=0;invalidate();}
 void rect(Canvas c,float x,float y,float w,float h,int color){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,9,9,p);}
 void text(Canvas c,String s,float x,float y,float size,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif-medium",0));c.drawText(s,x,y,p);}
 void step(float dt){if(winner!=-1)return; for(int i=0;i<n;i++){Car a=cars[i];if(a.hp<=0)continue;float steer=0,gas=0;for(float[] f:fingers.values()){int j=(int)(f[0]/(W/n));if(j!=i||f[1]<490)continue;float u=(f[0]-j*W/n)/(W/n);if(u<.25)steer=-1;else if(u<.5)steer=1;else if(u<.75)gas=-.55f;else gas=1;}a.a+=(steer*145+a.spin)*dt;a.spin*=Math.pow(.12,dt);float r=(float)Math.toRadians(a.a);float power=a.type==1?420:a.type==2?270:350;a.vx+=Math.cos(r)*gas*power*dt;a.vy+=Math.sin(r)*gas*power*dt;float drag=(float)Math.pow(.48,dt);a.vx*=drag;a.vy*=drag;float speed=(float)Math.hypot(a.vx,a.vy);if(speed>330){a.vx*=330/speed;a.vy*=330/speed;}a.x+=a.vx*dt;a.y+=a.vy*dt;if(a.x<48||a.x>1152){a.x=Math.max(48,Math.min(1152,a.x));a.hp-=Math.abs(a.vx)*.035f;a.vx*=-.65f;}if(a.y<95||a.y>445){a.y=Math.max(95,Math.min(445,a.y));a.hp-=Math.abs(a.vy)*.035f;a.vy*=-.65f;}}
 for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){Car a=cars[i],b=cars[j];float dx=b.x-a.x,dy=b.y-a.y,d=(float)Math.hypot(dx,dy);if(d>=58)continue;if(d<.01f){dx=1;dy=0;d=1;}float nx=dx/d,ny=dy/d,over=(58-d)/2;a.x-=nx*over;a.y-=ny*over;b.x+=nx*over;b.y+=ny*over;float v=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(v<0){float impulse=-1.65f*v/(1/a.mass+1/b.mass);a.vx-=impulse*nx/a.mass;a.vy-=impulse*ny/a.mass;b.vx+=impulse*nx/b.mass;b.vy+=impulse*ny/b.mass;float damage=Math.max(0,-v-25)*.10f;a.hp-=damage/a.mass;b.hp-=damage/b.mass;a.spin+=impulse*.45f;b.spin-=impulse*.45f;}}
 int alive=0,idx=-1;for(int i=0;i<n;i++){cars[i].hp=Math.max(0,cars[i].hp);if(cars[i].hp>0){alive++;idx=i;}}if(alive<=1)winner=alive==0?3:idx;
 }
 protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/W,getHeight()/H);c.drawColor(0xff10151e);
 if(n==0){text(c,"APEX / CRASH ARENA",65,95,55,-1);text(c,"LOCAL MULTIPLAYER  •  SELECT YOUR VEHICLES",65,145,25,0xff9daec3);for(int i=0;i<3;i++){rect(c,65+i*370,190,330,130,colors[i]);text(c,"P"+(i+1)+"  "+names[models[i]],85+i*370,265,34,0xff10151e);}rect(c,65,390,500,130,0xff24384e);rect(c,635,390,500,130,0xff24384e);text(c,"2 PLAYERS",200,470,40,-1);text(c,"3 PLAYERS",770,470,40,-1);c.restore();return;}
 long now=System.nanoTime();float dt=last==0?0:Math.min(.05f,(now-last)/1e9f);last=now;for(int k=0;k<3;k++)step(dt/3);rect(c,18,70,1164,410,0xff303945);for(int x=50;x<1180;x+=80){p.setColor(0xff46505a);c.drawLine(x,75,x,475,p);}for(int i=0;i<n;i++){Car a=cars[i];float seg=W/n; text(c,"P"+(i+1)+"  "+(int)a.hp+"%",i*seg+20,25,23,colors[i]);rect(c,i*seg+20,36,seg-40,15,0xff343b48);rect(c,i*seg+20,36,(seg-40)*a.hp/100,15,colors[i]);c.save();c.translate(a.x,a.y);c.rotate(a.a);rect(c,-29,-20,58,40,0xff10141a);rect(c,-34,-15,68,30,a.hp>0?colors[i]:0xff535353);rect(c,-12,-12,23,24,0xff182b3c);rect(c,25,-11,6,7,0xfff5f5da);rect(c,25,4,6,7,0xfff5f5da);if(a.hp<50){p.setColor(0xff171717);p.setStrokeWidth(3);c.drawLine(-20,-12,7,12,p);}c.restore();text(c,"P"+(i+1),a.x-12,a.y-28,18,-1);
 String[] labels={"LEFT","RIGHT","BRAKE","GAS"};for(int k=0;k<4;k++){float bw=seg/4;rect(c,i*seg+k*bw+4,495,bw-8,145,k==3?colors[i]:0xff263343);text(c,labels[k],i*seg+k*bw+8,575,Math.min(22,bw/3.2f),k==3?0xff10151e:-1);}}
 if(winner!=-1){rect(c,300,190,600,200,0xff141d2a);text(c,winner==3?"DRAW":"PLAYER "+(winner+1)+" WINS",370,265,48,-1);text(c,"TAP TO RETURN TO MENU",400,330,27,0xffaabbcc);}c.restore();postInvalidateOnAnimation();}
 public boolean onTouchEvent(android.view.MotionEvent e){int action=e.getActionMasked(),idx=e.getActionIndex();float x=e.getX(idx)*W/getWidth(),y=e.getY(idx)*H/getHeight();if(n==0){if(action==0){if(y>190&&y<320){int i=Math.min(2,Math.max(0,(int)((x-65)/370)));models[i]=(models[i]+1)%3;invalidate();}else if(y>390&&y<520)start(x<600?2:3);}return true;}if(winner!=-1&&action==0){n=0;fingers.clear();invalidate();return true;}if(action==1||action==6)fingers.remove(e.getPointerId(idx));else if(action==3)fingers.clear();else for(int i=0;i<e.getPointerCount();i++)fingers.put(e.getPointerId(i),new float[]{e.getX(i)*W/getWidth(),e.getY(i)*H/getHeight()});return true;}
 }
}